import{c as n,Q as s,j as e,m as t}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"项目简介","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1780637345000}'),l={name:"guide/index.md"};function o(r,a,i,p,d,c){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to &quot;项目简介&quot;">​</a></h1><h2 id="什么是白鹿工作流" tabindex="-1">什么是白鹿工作流？ <a class="header-anchor" href="#什么是白鹿工作流" aria-label="Permalink to &quot;什么是白鹿工作流？&quot;">​</a></h2><p><strong>白鹿工作流 CLI</strong>（<code>bailu</code>）是一款面向 <strong>AI 辅助开发</strong>的工作流管理工具，专为在多种 AI 编程工具之间统一管理配置文件和工作流组件而设计。</p><blockquote><p><strong>林深见鹿</strong>——在复杂的规则森林中，发现优雅的解决方案</p></blockquote><h2 id="核心价值" tabindex="-1">核心价值 <a class="header-anchor" href="#核心价值" aria-label="Permalink to &quot;核心价值&quot;">​</a></h2><p>白鹿工作流解决了以下核心痛点：</p><h3 id="配置碎片化" tabindex="-1">配置碎片化 <a class="header-anchor" href="#配置碎片化" aria-label="Permalink to &quot;配置碎片化&quot;">​</a></h3><p>AI 工具配置分散在各个目录，难以统一管理。白鹿工作流通过统一的配置中心（<code>~/.bailu/</code>）集中管理所有配置。</p><h3 id="团队不一致" tabindex="-1">团队不一致 <a class="header-anchor" href="#团队不一致" aria-label="Permalink to &quot;团队不一致&quot;">​</a></h3><p>团队成员使用的 AI 工具配置各不相同，协作效率低下。白鹿工作流通过 <code>sync</code> 命令保持团队配置同步。</p><h3 id="工作流复用难" tabindex="-1">工作流复用难 <a class="header-anchor" href="#工作流复用难" aria-label="Permalink to &quot;工作流复用难&quot;">​</a></h3><p>优质的 Skills/Commands/Agents/Rules 无法快速分享和复用。白鹿工作流将这些组件打包为可安装的工作流包。</p><h3 id="工具迷茫感" tabindex="-1">工具迷茫感 <a class="header-anchor" href="#工具迷茫感" aria-label="Permalink to &quot;工具迷茫感&quot;">​</a></h3><p>AI 编程工具种类繁多，难以快速找到适合自己的工具。白鹿工作流内置 AI 工具推荐系统。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>描述</th></tr></thead><tbody><tr><td><strong>团队协作</strong></td><td>统一团队 AI 工具配置，通过 sync 命令保持所有成员配置同步</td></tr><tr><td><strong>个人开发</strong></td><td>快速安装精心设计的工作流（dev/ops），提升 AI 辅助开发效率</td></tr><tr><td><strong>工具评估</strong></td><td>通过 recommend 命令浏览和发现优质 AI 编程工具</td></tr><tr><td><strong>MCP 管理</strong></td><td>统一管理 MCP（Model Context Protocol）服务配置</td></tr><tr><td><strong>代码质量</strong></td><td>通过 Git Hooks 和 audit 命令保障代码质量与安全</td></tr></tbody></table><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2><ul><li><strong>TUI 仪表盘</strong>：无参数运行 <code>bailu</code> 即可查看精美的终端仪表盘</li><li><strong>一键安装工作流</strong>：将精心设计的 dev/ops 工作流安装到目标 AI 工具</li><li><strong>多工具支持</strong>：支持 Claude Code、Codex、Cursor、Windsurf 等主流 AI 工具</li><li><strong>WebUI 管理平台</strong>：图形界面管理工作流、MCP 配置、推荐工具</li><li><strong>团队同步机制</strong>：基于 Git 的配置同步，保持团队统一</li><li><strong>AI 工具推荐</strong>：内置精选 AI 工具数据库，支持社区自定义推荐</li><li><strong>MCP 服务管理</strong>：便捷添加、删除、启用/禁用 MCP Server</li><li><strong>安全审计</strong>：对已安装的组件进行安全审计</li></ul><h2 id="技术架构" tabindex="-1">技术架构 <a class="header-anchor" href="#技术架构" aria-label="Permalink to &quot;技术架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    白鹿工作流 CLI                            │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  CLI 层 (Commander.js)                                      │</span></span>
<span class="line"><span>│  ├── bailu init          # 初始化配置                       │</span></span>
<span class="line"><span>│  ├── bailu workflow       # 工作流管理                       │</span></span>
<span class="line"><span>│  ├── bailu tool           # AI 工具管理                     │</span></span>
<span class="line"><span>│  ├── bailu mcp            # MCP 服务管理                    │</span></span>
<span class="line"><span>│  ├── bailu sync           # 团队同步                        │</span></span>
<span class="line"><span>│  └── bailu serve          # 启动 WebUI                      │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  配置层 (~/.bailu/)                                         │</span></span>
<span class="line"><span>│  ├── config/              # 工作流配置                       │</span></span>
<span class="line"><span>│  └── projects.json        # 项目配置                         │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  工具层                                                     │</span></span>
<span class="line"><span>│  ├── Claude Code          # ~/.claude/                      │</span></span>
<span class="line"><span>│  ├── Hanako               # ~/.hanako/                      │</span></span>
<span class="line"><span>│  ├── Codex                # ~/.codex/                       │</span></span>
<span class="line"><span>│  ├── Cursor               # ~/.cursor/                      │</span></span>
<span class="line"><span>│  └── 其他 AI 工具...                                        │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="许可协议" tabindex="-1">许可协议 <a class="header-anchor" href="#许可协议" aria-label="Permalink to &quot;许可协议&quot;">​</a></h2><p>白鹿工作流基于 MIT 许可协议开源。</p>`,22)])])}const b=n(l,[["render",o]]);export{u as __pageData,b as default};
